class BufferHandle {
    char* data_;
public:
    BufferHandle(size_t s) : data_(new char[s]) {}
    ~BufferHandle() { delete[] data_; }
    BufferHandle(const BufferHandle&) = delete;

    // Explicit Move Constructor: Zeroes out source state
    BufferHandle(BufferHandle&& other) noexcept
        : data_(std::exchange(other.data_, nullptr)) {}

    // Move Assignment
    BufferHandle& operator=(BufferHandle&& other) noexcept {
        if (this != &other) {
            delete[] data_;
            data_ = std::exchange(other.data_, nullptr);
        }
        return *this;
    }
};

// --- Perfect Forwarding in Stream Operation ---

namespace Stream {
    template <typename T>
    void sink(T&& item) {
        // Preserves the value category (lvalue or rvalue) of item
        detail::process_internal(std::forward<T>(item));
    }
}

namespace detail {
    // Overload for lvalue references
    void process_internal(const BufferHandle& h) { /* Read-only access */ }
    // Overload for rvalue references (allows move optimization)
    void process_internal(BufferHandle&& h) { /* Transfer ownership */ }
}
